  let n = start
  return () => ++n
}
const a = makeCounter()
a() // 1
a() // 2

function debounceLatest<T extends unknown[]>(fn: (...args: T) => void, ms: number) {
  let last: T
  let timer = 0
  return (...args: T) => {
    last = args // không phải args lần gọi #1
    clearTimeout(timer)
    timer = window.setTimeout(() => fn(...last), ms)
  }
}
```

Bộ đếm close over `n` — một binding, không phải snapshot. `debounceLatest` lưu `last` trên wrapper nên timeout luôn chạy với args mới nhất. Timeout close over `args` lần gọi #1 chính là bug closure stale.

