```ts
function demo() {
  if (true) {
    var leaked = 1
    let blocked = 2
  }
  console.log(leaked)  // 1 — function scope
  // console.log(blocked) // ReferenceError — block scope
}

let userCache = new Map() // module scope — lives for the session
export function loadUser(id: string) {
  // keep UI data in the caller / store, not here
  return fetch(`/api/users/${id}`).then((r) => r.json())
}
export function clearUserCache() {
  userCache = new Map() // logout must drop this root
}
```

`var` leaks out of the `if`. `let` does not. `userCache` is module-scoped: it survives every route until you clear it. That is a scope decision, not a closure puzzle.

