function throttle<T extends (...args: any[]) => void>(fn: T, wait = 300) {
  let lastRun = 0

  return (...args: Parameters<T>) => {
    const now = Date.now()
    if (now - lastRun >= wait) {
      lastRun = now
      fn(...args)
    }
  }
}
```

